const fotoBase64 = $json.foto_base64;
const cultivoId = $json.cultivo_id;
const timestamp = Date.now();
const path = `${cultivoId}/${timestamp}.jpg`;

return [{
  json: { ...$json, path_foto_evento: path },
  binary: {
    data: {
      data: fotoBase64,
      mimeType: 'image/jpeg',
      fileName: `${timestamp}.jpg`
    }
  }
}];

// ============================================================
// CONSOLIDAR DATOS — WF1
// Última actualización: 16/10/2026 (sesión 16) — incluye 16.34 y 13.7.2
// ============================================================
const motor = $('Motor de Inferencia').item.json;

let pathFotoEvento = null;
let pathFotoWarn = null;
try {
  pathFotoEvento = $('Preparar Foto binaria').first()?.json?.path_foto_evento ?? null;
} catch (e) {
  // Caso esperado: no había foto, esta rama no corrió.
  // Caso bug: el nodo no existe o cambió de nombre — queda registrado en vez de morir en silencio.
  pathFotoEvento = null;
  pathFotoWarn = e.message;
}

// ============================================================
// 16.34 — EL CUERPO DE LA RPC SE ARMA COMO OBJETO, NUNCA CONCATENANDO TEXTO
// ------------------------------------------------------------
// `fn_registrar_telemetria` declara sus 5 métricas como DEFAULT NULL y filtra con
// `WHERE v.valor IS NOT NULL`: acepta lecturas parciales POR DISEÑO. El nodo que la
// llamaba armaba el JSON interpolando texto, así que un sensor que no reportaba
// dejaba el cuerpo como `"p_humedad": ,` — JSON inválido, telemetría perdida entera.
// Acá el cliente pasa a poder expresar lo que la base ya sabía recibir.
// ============================================================

// OJO con la coerción: Number(null) === 0 y Number('') === 0.
// Un sensor ausente convertido a 0 no es un dato faltante: es una lectura de 0%
// de humedad, que el Motor interpreta como sequía y que dispara riego real.
// Por eso la ausencia se decide ANTES de convertir, nunca después.
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const rpcTelemetria = {
  p_cultivo_id:     motor.cultivo_id,
  p_dispositivo_id: motor.dispositivo_id,
  p_humedad: num(motor.humedad),
  p_ph:      num(motor.ph),
  p_n:       num(motor.n),
  p_p:       num(motor.p),
  p_k:       num(motor.k)
};

// Validación positiva, no negativa: se verifica afirmativamente que están los dos
// campos de identidad. Una fila de telemetría sin cultivo es peor que una perdida,
// porque queda en la base y miente.
if (!rpcTelemetria.p_cultivo_id || !rpcTelemetria.p_dispositivo_id) {
  throw new Error(
    'Consolidar datos: falta cultivo_id o dispositivo_id — no se registra telemetría sin identidad. ' +
    `mac=${motor.mac_address ?? 'desconocida'}`
  );
}

// ============================================================
// 13.7.2 — CUERPO DE fn_registrar_recheck_riego, también como objeto (16.34)
// ------------------------------------------------------------
// `Registrar Recheck de Riego` llama en CADA lectura: si esta lectura no es un
// recheck, va p_evento_id null y la función no hace nada. Así no hace falta un
// IF que abra una rama paralela en el camino principal.
// Validación positiva: el Motor tiene que haber emitido el campo, aunque sea null.
// Si falta, el Motor es una versión vieja y el freno de riego no funciona.
// ============================================================
if (!('recheck_riego' in motor)) {
  throw new Error('Consolidar datos: el Motor no emitió recheck_riego — falta actualizar el Motor de Inferencia (13.7.2).');
}
const rc = motor.recheck_riego;
const rpcRecheck = {
  p_cultivo_id: motor.cultivo_id,
  p_evento_id:  rc ? rc.evento_id : null,
  p_humedad:    rc ? rc.humedad   : null,
  p_resultado:  rc ? rc.resultado : null
};

// Cuántas métricas trae realmente esta lectura. Un fallo manejado tiene que seguir
// siendo contado: si esto llega a 0, la RPC escribiría cero filas sin dar error,
// y eso es una señal operativa, no un caso normal.
const metricasPresentes = ['p_humedad', 'p_ph', 'p_n', 'p_p', 'p_k']
  .filter(k => rpcTelemetria[k] !== null).length;

return [{
  json: {
    ...motor,
    path_foto_evento: pathFotoEvento,
    path_foto_warn: pathFotoWarn,
    rpc_telemetria: rpcTelemetria,
    rpc_recheck: rpcRecheck,
    metricas_presentes: metricasPresentes
  }
}];
